class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self._options: dict[str, int] = {}
        self._voters: set[str] = set()

    def add_option(self, option: str) -> None:
        if option not in self._options:
            self._options[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self._options:
            raise ValueError(f"Option '{option}' does not exist.")
        if voter in self._voters:
            raise ValueError(f"Voter '{voter}' has already voted.")

        self._voters.add(voter)
        self._options[option] += 1

    def results(self) -> dict[str, int]:
        return self._options.copy()

    def winner(self) -> str | None:
        if len(self._voters) < 3:
            return None

        # Iterate in reverse order of addition so that in case of a tie,
        # the option added last is preferred.
        max_votes = -1
        best_option = None

        for option in reversed(self._options):
            votes = self._options[option]
            if votes > max_votes:
                max_votes = votes
                best_option = option

        return best_option
```

